contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function test(address owner, address recipient, uint256 amount) public payable {
        require(amount > 0);
        require(recipient != address(this));

        // Setup: deposit some Ether into C
        address(c).call{value: amount}("");

        // Ensure this contract is owner
        // We rely on the fact that C's owner is set in its constructor.
        // For the rule to be general, we let the test caller provide the owner,
        // and we trust that the test harness initializes C correctly.
        // Since we cannot change C's owner, we check that the provided owner matches C's actual owner.
        require(c.owner() == owner);

        uint256 balanceBefore = address(c).balance;
        uint256 recipientBalanceBefore = recipient.balance;
        uint256 thisBalanceBefore = address(this).balance;

        // The deciding call, pretending to be owner (since this contract is not owner, we expect revert)
        // To observe the difference, we need a successful call, so we make the test contract the owner.
        // Since we cannot change owner, we require that the test contract IS the owner.
        require(address(this) == owner);

        c.withdrawAll(recipient);

        uint256 recipientBalanceAfter = recipient.balance;
        uint256 thisBalanceAfter = address(this).balance;

        // General rule: After withdrawal, the entire C balance went to the recipient,
        // and none stayed in C. Also, the caller (this contract) should not receive the funds.
        // The change in M sends funds to msg.sender instead of recipient.
        assert(
            address(c).balance == 0 &&
            recipientBalanceAfter == recipientBalanceBefore + balanceBefore &&
            thisBalanceAfter == thisBalanceBefore
        );
    }

    receive() external payable {}
    fallback() external payable {}
}

