        // Restrict to admissible domain: sender not zero, sender not contract owner, amount > 0, recipient not contract address
        vm.assume(sender != address(0) && sender != address(this) && amount > 0 && recipient != address(c) && recipient != address(0));
        // Fund contract
        vm.deal(address(c), amount);
        // Record recipient's initial balance
        uint256 recipientBefore = recipient.balance;
        // Attempt withdrawal as sender; only the contract owner (address(this)) succeeds, so this prank will fail
