pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 amount, address recipient) public {
        // Owner is address(this). Ensure a non-zero amount and avoid overflow, restrict recipient to be different from owner.
        vm.assume(amount > 0 && amount <= address(this).balance);
        vm.assume(recipient != address(this));
        // Fund the contract.
        vm.deal(address(c), amount);
        uint256 ownerBalanceBefore = address(this).balance;
        // Owner withdraws.
        c.withdrawAll(recipient);
        uint256 ownerBalanceAfter = address(this).balance;
        // After a valid withdrawal, the contract balance must be zero, and the owner (msg.sender) must not have gained the withdrawn funds.
        // The gas cost decreases the owner's balance slightly, so ownerBalanceAfter <= ownerBalanceBefore.
        assertTrue(
            address(c).balance == 0 && ownerBalanceAfter <= ownerBalanceBefore
        );
    }
}
